(963704, 113504, 28122, '<td valign="top">very nice shot!</td>', 'very nice shot!', '2004-10-18 11:09:57.000000', NULL, 1),
(963705, 113647, 10390, '<td valign="top">Good photo.  A person leaning to the curved wall would make this image even better, well seen and well framed.</td>', 'Good photo.  A person leaning to the curved wall would make this image even better, well seen and well framed.', '2004-10-18 11:11:11.000000', NULL, 1),
