(964043, 113263, 18197, '<td valign="top">I am generally not a fan of this type of partial exposure photo. In this case, however it is so well done it is among my top picks. The semi-transparent model even casts a semi-transparent shadow. Really really well done. Congratulations.</td>', 'I am generally not a fan of this type of partial exposure photo. In this case, however it is so well done it is among my top picks. The semi-transparent model even casts a semi-transparent shadow. Really really well done. Congratulations.', '2004-10-18 16:39:28.000000', NULL, 1),
(964044, 113647, 3569, '<td valign="top">Love the eay you let my eye back to the building.</td>', 'Love the eay you let my eye back to the building.', '2004-10-18 16:40:27.000000', NULL, 1),
