(964065, 113485, 18197, '<td valign="top">I find the leaves turning from green to red somewhat interesting, but the overall photo doesn''t sustain my interest. It feels too busy to me. Not sure of the light source, possibly your flash, but the lighting feels pretty harsh.</td>', 'I find the leaves turning from green to red somewhat interesting, but the overall photo doesn''t sustain my interest. It feels too busy to me. Not sure of the light source, possibly your flash, but the lighting feels pretty harsh.', '2004-10-18 16:48:43.000000', NULL, 1),
(964066, 112357, 24962, '<td valign="top">This is a truly atmospheric photo. Can''t find anything you need to change. Given it a 10...though 11 would be better. Well Done.</td>', 'This is a truly atmospheric photo. Can''t find anything you need to change. Given it a 10...though 11 would be better. Well Done.', '2004-10-18 16:48:46.000000', NULL, 1),
(964067, 112942, 13136, '<td valign="top">I love the angle of this shot as well as how crisp the blacks are.</td>', 'I love the angle of this shot as well as how crisp the blacks are.', '2004-10-18 16:48:54.000000', NULL, 1),
(964069, 113691, 18197, '<td valign="top">Cute kids ready for bed. I like that. It''s an innovative approach to the theme. Good luck.</td>', 'Cute kids ready for bed. I like that. It''s an innovative approach to the theme. Good luck.', '2004-10-18 16:49:59.000000', NULL, 1),
