(964139, 112640, 27524, '<td valign="top">You get me curious... have bridge like that in my city too. Real nice colors... well done.</td>', 'You get me curious... have bridge like that in my city too. Real nice colors... well done.', '2004-10-18 17:34:06.000000', NULL, 1),
(964141, 113686, 24911, '<td valign="top">Love the colors and the composition. The reflections on the water are great.8.</td>', 'Love the colors and the composition. The reflections on the water are great.8.', '2004-10-18 17:34:27.000000', NULL, 1),
(964143, 113526, 24911, '<td valign="top">It has a "dream" effect to it, and I like it. Nice colors. good composition. 8.</td>', 'It has a "dream" effect to it, and I like it. Nice colors. good composition. 8.', '2004-10-18 17:35:51.000000', NULL, 1),
