(964149, 113327, 24911, '<td valign="top">Fantastic shot, and a really sharp one!. Interesting enough subject. Good composition.8.</td>', 'Fantastic shot, and a really sharp one!. Interesting enough subject. Good composition.8.', '2004-10-18 17:38:58.000000', NULL, 1),
