(964170, 113368, 24911, '<td valign="top">Loved it! the colors. The composition. the cubject. Good work. 9.</td>', 'Loved it! the colors. The composition. the cubject. Good work. 9.', '2004-10-18 17:51:02.000000', NULL, 1),
(964171, 113315, 24911, '<td valign="top">Interesting subject. good composition. 8.</td>', 'Interesting subject. good composition. 8.', '2004-10-18 17:52:53.000000', NULL, 1),
(964174, 113607, 24911, '<td valign="top">Loved the idea. Simple but nice. Good colors and lights. 9.</td>', 'Loved the idea. Simple but nice. Good colors and lights. 9.', '2004-10-18 17:55:46.000000', NULL, 1),
(964175, 112973, 27524, '<td valign="top">Really like tones of colors... real juicy. Somehow feels that vertical title looks better then horizontal one.</td>', 'Really like tones of colors... real juicy. Somehow feels that vertical title looks better then horizontal one.', '2004-10-18 17:55:57.000000', NULL, 1),
