(964180, 113142, 27524, '<td valign="top">Im catched by idea but something went wrong with focus.</td>', 'Im catched by idea but something went wrong with focus.', '2004-10-18 17:59:28.000000', NULL, 1),
(964182, 112927, 26756, '<td valign="top">Good focus and exposure.  None of the lights are blown out and you managed to capture the detail of the building nicely.  The black and white works too.</td>', 'Good focus and exposure.  None of the lights are blown out and you managed to capture the detail of the building nicely.  The black and white works too.', '2004-10-18 18:00:13.000000', NULL, 1),
(964184, 113319, 27524, '<td valign="top">Uhh people... amazin expression...even scary... and these old branches of tree. Great shot. Good luck.</td>', 'Uhh people... amazin expression...even scary... and these old branches of tree. Great shot. Good luck.', '2004-10-18 18:01:22.000000', NULL, 1),
(964185, 112357, 27524, '<td valign="top">Sigh... treasurous to capture such moments...</td>', 'Sigh... treasurous to capture such moments...', '2004-10-18 18:02:39.000000', NULL, 1),
(964187, 112695, 27524, '<td valign="top">Real colorful corner of your city...good colors.</td>', 'Real colorful corner of your city...good colors.', '2004-10-18 18:04:26.000000', NULL, 1),
(964188, 113701, 27524, '<td valign="top">Uhh :) no way. You had good idea...just seems luck of light at that spot... so you had to overdose with contrast. Pitty cant see fence between.</td>', 'Uhh :) no way. You had good idea...just seems luck of light at that spot... so you had to overdose with contrast. Pitty cant see fence between.', '2004-10-18 18:06:16.000000', NULL, 1),
(964189, 113440, 26756, '<td valign="top">The lights on the temple are really good and the angle of view gives it a "majestic" feeling.  IMO, I would have cropped out the red light to the bottom left.  It doesn''t really add anything to the photo and draws your eyes from the main subject.  Beautiful shot though.</td>', 'The lights on the temple are really good and the angle of view gives it a "majestic" feeling.  IMO, I would have cropped out the red light to the bottom left.  It doesn''t really add anything to the photo and draws your eyes from the main subject.  Beautiful shot though.', '2004-10-18 18:06:32.000000', NULL, 1),
(964190, 113679, 26756, '<td valign="top">For me there is no really strong point of interest for the eyes to settle on.  The lake is a bit dark to make a strong subject as well as the far shore.  I do like the sky and the colors of the shot.</td>', 'For me there is no really strong point of interest for the eyes to settle on.  The lake is a bit dark to make a strong subject as well as the far shore.  I do like the sky and the colors of the shot.', '2004-10-18 18:08:27.000000', NULL, 1),
(964191, 113386, 27524, '<td valign="top">Reflections on water are impressive... lot of objects in picture...maybe bit too much to get real cought.</td>', 'Reflections on water are impressive... lot of objects in picture...maybe bit too much to get real cought.', '2004-10-18 18:09:07.000000', NULL, 1),
(964192, 113621, 27524, '<td valign="top">I like... sharp details...good focus and cropping. Good luck.</td>', 'I like... sharp details...good focus and cropping. Good luck.', '2004-10-18 18:10:38.000000', NULL, 1),
(964194, 112795, 27524, '<td valign="top">Amazing again :)... that train looks like toy...and ore like sugar... Wish you decent placing for this. Good luck.</td>', 'Amazing again :)... that train looks like toy...and ore like sugar... Wish you decent placing for this. Good luck.', '2004-10-18 18:14:14.000000', NULL, 1),
(964197, 113097, 27524, '<td valign="top">What the mixture of colors... real flashy.</td>', 'What the mixture of colors... real flashy.', '2004-10-18 18:16:28.000000', NULL, 1),
(964207, 113429, 26045, '<td valign="top">WOW! I love this! Colors are fab, excellent sharpness in the reflection...the sky looks a little too bright, especially as compared to the reflection...but I''m diggin'' this so  much! 10!</td>', 'WOW! I love this! Colors are fab, excellent sharpness in the reflection...the sky looks a little too bright, especially as compared to the reflection...but I''m diggin'' this so  much! 10!', '2004-10-18 18:24:13.000000', NULL, 1),
(964208, 113348, 26045, '<td valign="top">Niiiiiiiice! This is tops in my book! 10</td>', 'Niiiiiiiice! This is tops in my book! 10', '2004-10-18 18:25:13.000000', NULL, 1),
(964209, 112357, 26045, '<td valign="top">This...is...so...rad! I love it! Great shot, great title, excellent mood. 10 all the way.</td>', 'This...is...so...rad! I love it! Great shot, great title, excellent mood. 10 all the way.', '2004-10-18 18:26:24.000000', NULL, 1),
(964217, 113259, 25143, '<td valign="top">great shot and colors</td>', 'great shot and colors', '2004-10-18 18:33:28.000000', NULL, 1),
