(964222, 112648, 25143, '<td valign="top">great color display</td>', 'great color display', '2004-10-18 18:35:10.000000', NULL, 1),
(964228, 113643, 25143, '<td valign="top">the slight tilt to the right bothers me a bit - apart from that I like the composition and color mood very much</td>', 'the slight tilt to the right bothers me a bit - apart from that I like the composition and color mood very much', '2004-10-18 18:39:30.000000', NULL, 1),
