(964231, 113349, 25143, '<td valign="top">nicely surreal colors and ambience</td>', 'nicely surreal colors and ambience', '2004-10-18 18:42:42.000000', NULL, 1),
(964232, 113315, 25143, '<td valign="top">great idea !! great horizontal division , too</td>', 'great idea !! great horizontal division , too', '2004-10-18 18:43:39.000000', NULL, 1),
(964233, 113167, 28070, '<td valign="top">looks like a big water droplet.  Excellent photo.</td>', 'looks like a big water droplet.  Excellent photo.', '2004-10-18 18:43:46.000000', NULL, 1),
(964235, 113519, 25143, '<td valign="top">not too flattering for your model but a neat idea nonetheless</td>', 'not too flattering for your model but a neat idea nonetheless', '2004-10-18 18:45:38.000000', NULL, 1),
(964238, 113680, 25143, '<td valign="top">too much light ! a bit of mystery shadow would have been nicer</td>', 'too much light ! a bit of mystery shadow would have been nicer', '2004-10-18 18:47:15.000000', NULL, 1),
(964240, 113495, 28070, '<td valign="top">I like the brilliance of the green and red across the water.</td>', 'I like the brilliance of the green and red across the water.', '2004-10-18 18:47:51.000000', NULL, 1),
(964241, 113127, 28070, '<td valign="top">I like it. calm water.</td>', 'I like it. calm water.', '2004-10-18 18:49:14.000000', NULL, 1),
(964243, 113516, 25143, '<td valign="top">nice idea but the unfocused texture in the foreground is too distracting - why not cut more top and bottom of the picture ?</td>', 'nice idea but the unfocused texture in the foreground is too distracting - why not cut more top and bottom of the picture ?', '2004-10-18 18:50:10.000000', NULL, 1),
(964244, 113569, 28070, '<td valign="top">I think it needs something in front of the pines as well. Good fill flash on the pines though.</td>', 'I think it needs something in front of the pines as well. Good fill flash on the pines though.', '2004-10-18 18:51:29.000000', NULL, 1),
(964247, 113348, 28070, '<td valign="top">extraordinary, I must say the best I''ve seen so far. Nice angle too.</td>', 'extraordinary, I must say the best I''ve seen so far. Nice angle too.', '2004-10-18 18:54:16.000000', NULL, 1),
(964249, 113115, 28070, '<td valign="top">Great shot.</td>', 'Great shot.', '2004-10-18 18:58:32.000000', NULL, 1),
(964251, 113506, 20066, '<td valign="top">Ég held nú eiginlega að þetta skilti þýði að maður verði að einbeita sér dálítið við að horfa bara á veginn!</td>', 'Ég held nú eiginlega að þetta skilti þýði að maður verði að einbeita sér dálítið við að horfa bara á veginn!', '2004-10-18 19:02:00.000000', NULL, 1),
(964252, 113429, 28070, '<td valign="top">Wow I like this shot.  Golden.</td>', 'Wow I like this shot.  Golden.', '2004-10-18 19:02:45.000000', NULL, 1),
(964254, 113699, 28070, '<td valign="top">The tilt makes it interesting.</td>', 'The tilt makes it interesting.', '2004-10-18 19:04:12.000000', NULL, 1),
(964256, 113620, 28070, '<td valign="top">Cool single streaks.  I would guess a Taxi or pizza delivery vehicle by the upper streak.</td>', 'Cool single streaks.  I would guess a Taxi or pizza delivery vehicle by the upper streak.', '2004-10-18 19:07:30.000000', NULL, 1),
(964265, 113519, 2553, '<td valign="top">OK, I''ve spent quite a bit of time looking at this trying to determine if there is anything that I like about it, but there is not, I''m sorry.  The lighting makes your model appear to look very strange, and to me, unappealing.  The composition is not appealing to me either, and quite frankly this just feels like gratuitous nudity. With nudes, I prefer photographs that try to represent the body as the beautiful creation that it is, not just an attempt to get nudity into the shot.</td>', 'OK, I''ve spent quite a bit of time looking at this trying to determine if there is anything that I like about it, but there is not, I''m sorry.  The lighting makes your model appear to look very strange, and to me, unappealing.  The composition is not appealing to me either, and quite frankly this just feels like gratuitous nudity. With nudes, I prefer photographs that try to represent the body as the beautiful creation that it is, not just an attempt to get nudity into the shot.', '2004-10-18 19:17:20.000000', NULL, 1),
(964266, 113532, 28070, '<td valign="top">excellent shot.  Just the right light.</td>', 'excellent shot.  Just the right light.', '2004-10-18 19:18:12.000000', NULL, 1),
(964267, 113599, 2553, '<td valign="top">I''m just not crazy about this shot, I''m sorry.  The composition fails to pull the elements of the photograph together in a way that is appealing.  The very bright turquoise/blue spot of the turn signal sticks out like a sore thumb, effectively making the eyes go right to it, and then it''s difficult to really look at anything else.The subject matter isn''t interesting enough to make it a stand out shot, and the shot isn''t done in enough of an "out of the box" style to make the subject matter interesting.</td>', 'I''m just not crazy about this shot, I''m sorry.  The composition fails to pull the elements of the photograph together in a way that is appealing.  The very bright turquoise/blue spot of the turn signal sticks out like a sore thumb, effectively making the eyes go right to it, and then it''s difficult to really look at anything else.The subject matter isn''t interesting enough to make it a stand out shot, and the shot isn''t done in enough of an "out of the box" style to make the subject matter interesting.', '2004-10-18 19:21:53.000000', NULL, 1),
(964272, 113652, 28070, '<td valign="top">I like the blurred clouds<br/></td>', 'I like the blurred clouds', '2004-10-18 19:28:57.000000', NULL, 1),
(964278, 113410, 28070, '<td valign="top">You can see where the bumps are in the road. nicely framed.</td>', 'You can see where the bumps are in the road. nicely framed.', '2004-10-18 19:32:21.000000', NULL, 1),
(964285, 112940, 28070, '<td valign="top">I love it.  The proven rotation of the earth.</td>', 'I love it.  The proven rotation of the earth.', '2004-10-18 19:42:18.000000', NULL, 1),
(964287, 112544, 2553, '<td valign="top">I''ve looked at this on all 3 computers in my office, and in all cases find this to be VERY dark.  I can barely make out any details. It''s definitely a night shot, but I was hoping to be able to make out a little more of what your night subject is.</td>', 'I''ve looked at this on all 3 computers in my office, and in all cases find this to be VERY dark.  I can barely make out any details. It''s definitely a night shot, but I was hoping to be able to make out a little more of what your night subject is.', '2004-10-18 19:43:28.000000', NULL, 1),
(964289, 113108, 28070, '<td valign="top">I like how it captured the reflection of the lights off the hood of the car too.  Kinda looks like smoke.</td>', 'I like how it captured the reflection of the lights off the hood of the car too.  Kinda looks like smoke.', '2004-10-18 19:45:17.000000', NULL, 1),
(964290, 113467, 24642, '<td valign="top">Splendid lighting and composition.  The tower and building look magnificent.  You also hit a soft spot because I have a weekness for boats.  -10</td>', 'Splendid lighting and composition.  The tower and building look magnificent.  You also hit a soft spot because I have a weekness for boats.  -10', '2004-10-18 19:45:46.000000', NULL, 1),
(964291, 112536, 13602, '<td valign="top">Beautiful colors and reflection, verry well executed, but compositionally probably a bit boreing. I think you maybe could find a better angle.</td>', 'Beautiful colors and reflection, verry well executed, but compositionally probably a bit boreing. I think you maybe could find a better angle.', '2004-10-18 19:46:18.000000', NULL, 1),
(964293, 113679, 2553, '<td valign="top">I like the purple glow of the lights behind the trees/houses, and I like the kind of silhouette look of the trees and buildings.  The lighted foreground really hurts this shot for me, completely taking away from the top part of the photo.  It''s almost like two different shots merged together.</td>', 'I like the purple glow of the lights behind the trees/houses, and I like the kind of silhouette look of the trees and buildings.  The lighted foreground really hurts this shot for me, completely taking away from the top part of the photo.  It''s almost like two different shots merged together.', '2004-10-18 19:46:58.000000', NULL, 1),
(964294, 113142, 13602, '<td valign="top">Beautiful image, but there is some disturbing compression artifacts looking like stuff all over it.</td>', 'Beautiful image, but there is some disturbing compression artifacts looking like stuff all over it.', '2004-10-18 19:47:31.000000', NULL, 1),
(964295, 113682, 24642, '<td valign="top">Great texture, good composition.  Gives me the impression of a very cold and impersonal place.  -9</td>', 'Great texture, good composition.  Gives me the impression of a very cold and impersonal place.  -9', '2004-10-18 19:47:54.000000', NULL, 1),
(964298, 113495, 13602, '<td valign="top">This is wonderful, the colors the reflection composition, everything. 10</td>', 'This is wonderful, the colors the reflection composition, everything. 10', '2004-10-18 19:48:56.000000', NULL, 1),
(964299, 113559, 24642, '<td valign="top">Cool and dramatic composition.  One of my favorites.  -9</td>', 'Cool and dramatic composition.  One of my favorites.  -9', '2004-10-18 19:49:52.000000', NULL, 1),
(964300, 113581, 13602, '<td valign="top">use tripod on long exposures, the focus is moved here.</td>', 'use tripod on long exposures, the focus is moved here.', '2004-10-18 19:50:19.000000', NULL, 1),
(964302, 113315, 24642, '<td valign="top">Good viewpoint.  Great balance between the lights and the pumpkins.  The lights have funny but nice a christmas feel.  -9</td>', 'Good viewpoint.  Great balance between the lights and the pumpkins.  The lights have funny but nice a christmas feel.  -9', '2004-10-18 19:51:59.000000', NULL, 1),
(964303, 113519, 13602, '<td valign="top">interesting, however even if I don''t ususaly dislike grain in images, the grain here is not nice.</td>', 'interesting, however even if I don''t ususaly dislike grain in images, the grain here is not nice.', '2004-10-18 19:52:06.000000', NULL, 1),
(964306, 113663, 13602, '<td valign="top">Verry nice however I disagree with the choice for a square image here. It makes the everything  too centered.</td>', 'Verry nice however I disagree with the choice for a square image here. It makes the everything  too centered.', '2004-10-18 19:53:29.000000', NULL, 1),
(964307, 113141, 24642, '<td valign="top">Grand colours and harmony between the shelves and the sky and the pumpkins and the trees.  Very good viewpoint.  The colour in the trees is brilliant.  -9</td>', 'Grand colours and harmony between the shelves and the sky and the pumpkins and the trees.  Very good viewpoint.  The colour in the trees is brilliant.  -9', '2004-10-18 19:54:05.000000', NULL, 1),
(964308, 112924, 13602, '<td valign="top">This is a sunset. The image is suposed to be after sunset. Otherways a verry beautiful one.</td>', 'This is a sunset. The image is suposed to be after sunset. Otherways a verry beautiful one.', '2004-10-18 19:54:37.000000', NULL, 1),
(964309, 113127, 24642, '<td valign="top">My favorite of the architecture shots.  good viewpoint and composition.  -9</td>', 'My favorite of the architecture shots.  good viewpoint and composition.  -9', '2004-10-18 19:54:57.000000', NULL, 1),
(964310, 112901, 28070, '<td valign="top">I think it needs to be darker with more lights turned on for the city part. the water is cool. And I  guess you could only get that color with the evening light as it  was.</td>', 'I think it needs to be darker with more lights turned on for the city part. the water is cool. And I  guess you could only get that color with the evening light as it  was.', '2004-10-18 19:55:02.000000', NULL, 1),
(964312, 113433, 13602, '<td valign="top">I don''t understand your composition choice, a beautiful complementary color contrast there but the composition is not the best I think.</td>', 'I don''t understand your composition choice, a beautiful complementary color contrast there but the composition is not the best I think.', '2004-10-18 19:56:14.000000', NULL, 1),
(964314, 113504, 28070, '<td valign="top">Nicely done. The dandy lions look like big trees almost.</td>', 'Nicely done. The dandy lions look like big trees almost.', '2004-10-18 19:56:39.000000', NULL, 1),
(964315, 113672, 24642, '<td valign="top">I like the idea.</td>', 'I like the idea.', '2004-10-18 19:56:50.000000', NULL, 1),
(964317, 112717, 2553, '<td valign="top">Nice color and I like the lines and angles, but overall the shot doesn''t have a lot of impact for me.  Whether the subject is the person, or the stairs, there is nothing  that really catches my interest, and there just isn''t any of the "wow" factor that would make it a stand out for me.</td>', 'Nice color and I like the lines and angles, but overall the shot doesn''t have a lot of impact for me.  Whether the subject is the person, or the stairs, there is nothing  that really catches my interest, and there just isn''t any of the "wow" factor that would make it a stand out for me.', '2004-10-18 19:57:27.000000', NULL, 1),
(964318, 113621, 13602, '<td valign="top">Absolutely beautiful!</td>', 'Absolutely beautiful!', '2004-10-18 19:58:05.000000', NULL, 1),
(964319, 112927, 24642, '<td valign="top">Good viewpoint and cropping.  I also like that you choose to have it a monochrome.  The cars really help to get the scale of the building.  Good work.  -8<br/><br/><i>Message edited by author 2004-10-27 19:20:11.</i></td>', 'Good viewpoint and cropping.  I also like that you choose to have it a monochrome.  The cars really help to get the scale of the building.  Good work.  -8', '2004-10-18 19:59:10.000000', '2004-10-27 20:20:11.000000', 1),
(964321, 113263, 13602, '<td valign="top">Great long exposure, great ideea.</td>', 'Great long exposure, great ideea.', '2004-10-18 19:59:50.000000', NULL, 1),
(964322, 113678, 2553, '<td valign="top">Interesting in an abstract way,  a fairly effective use of negative space, and the perspective gives it a pretty good composition, but the photo, as a whole, has little impact for me.</td>', 'Interesting in an abstract way,  a fairly effective use of negative space, and the perspective gives it a pretty good composition, but the photo, as a whole, has little impact for me.', '2004-10-18 20:00:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(964324, 113315, 13602, '<td valign="top">Wonderful composition, verry interesting image, but why so much sharpening? You ruined it for me.</td>', 'Wonderful composition, verry interesting image, but why so much sharpening? You ruined it for me.', '2004-10-18 20:01:03.000000', NULL, 1),
(964327, 113108, 13602, '<td valign="top">wonderful, verry well done.</td>', 'wonderful, verry well done.', '2004-10-18 20:02:57.000000', NULL, 1),
(964328, 113600, 28070, '<td valign="top">Blurry</td>', 'Blurry', '2004-10-18 20:03:04.000000', NULL, 1),
(964329, 112544, 24642, '<td valign="top">My jaw drops when photograpny meets painting, very elegant.  One of a few shots without bright lights which is a relief in this challenge.  Good composition and viewpoint and the colors are fantastic.   Good job on the border.  -10</td>', 'My jaw drops when photograpny meets painting, very elegant.  One of a few shots without bright lights which is a relief in this challenge.  Good composition and viewpoint and the colors are fantastic.   Good job on the border.  -10', '2004-10-18 20:03:17.000000', NULL, 1),
(964331, 113330, 2553, '<td valign="top">Pretty colors, but the angle of the shot makes it difficult for me to determine what the heck this is that I am looking at - (a building, a sign??).  The composition/crop feels a little unbalanced since the very colorful part of the photo goes all the way off the edge on the left, but the right side is dark.</td>', 'Pretty colors, but the angle of the shot makes it difficult for me to determine what the heck this is that I am looking at - (a building, a sign??).  The composition/crop feels a little unbalanced since the very colorful part of the photo goes all the way off the edge on the left, but the right side is dark.', '2004-10-18 20:03:47.000000', NULL, 1),
