(964348, 113507, 2553, '<td valign="top">Since you submitted this shot, and I''m supposing that you actually saw it before you entered it, I''m guessing that you were going for abstraction on purpose, and if so, then I guess I don''t really care for it.  Some nice colors though.</td>', 'Since you submitted this shot, and I''m supposing that you actually saw it before you entered it, I''m guessing that you were going for abstraction on purpose, and if so, then I guess I don''t really care for it.  Some nice colors though.', '2004-10-18 20:11:38.000000', NULL, 1),
(964352, 113533, 13602, '<td valign="top">Usualy I don''t like this long exposure effects, (when they are used unproperly) but you used it perfectly here. I mean looking at your image really makes me dizzy, this is great.</td>', 'Usualy I don''t like this long exposure effects, (when they are used unproperly) but you used it perfectly here. I mean looking at your image really makes me dizzy, this is great.', '2004-10-18 20:12:35.000000', NULL, 1),
(964354, 113519, 24642, '<td valign="top">The most original shot in the challenge.  Very good composition.  I also like the lowercase title and that you choose to title it like you did, not electric body.  -8</td>', 'The most original shot in the challenge.  Very good composition.  I also like the lowercase title and that you choose to title it like you did, not electric body.  -8', '2004-10-18 20:13:06.000000', NULL, 1),
