(966535, 113225, 27294, '<td valign="top">I think the church is fading into the background just a little too much - but it is a tough call because then you would loose the detail in the glass... (which was well caught!)</td>', 'I think the church is fading into the background just a little too much - but it is a tough call because then you would loose the detail in the glass... (which was well caught!)', '2004-10-20 08:44:09.000000', NULL, 1),
(966537, 112717, 27294, '<td valign="top">I like this.  simple composition.  leaves you wanting to find out where the person is escaping from.  The whole hue gives it a forboding feeling as well.  The diagonal of the stairs works well.</td>', 'I like this.  simple composition.  leaves you wanting to find out where the person is escaping from.  The whole hue gives it a forboding feeling as well.  The diagonal of the stairs works well.', '2004-10-20 08:48:16.000000', NULL, 1),
