(966953, 113220, 23478, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2004-10-20 14:33:15.000000', NULL, 1),
(966955, 113581, 16004, '<td valign="top">wow, what a gorgeous building!  so white and smooth.  big sharp corners...  as you are no doubt aware, the shot has evidentally suffered from camera shake.  probably not evident from the lcd, right?  way around this is to rest your camera on any flat surface close to hand and use the built-in timer.  will give you a far sharper shot.  recommend buying a little 5 inch tripod that is less than 20 bucks and is incredibly useful - get from any camera shop.  this shot certainly has tonnes of promise.  keep at it!</td>', 'wow, what a gorgeous building!  so white and smooth.  big sharp corners...  as you are no doubt aware, the shot has evidentally suffered from camera shake.  probably not evident from the lcd, right?  way around this is to rest your camera on any flat surface close to hand and use the built-in timer.  will give you a far sharper shot.  recommend buying a little 5 inch tripod that is less than 20 bucks and is incredibly useful - get from any camera shop.  this shot certainly has tonnes of promise.  keep at it!', '2004-10-20 14:34:09.000000', NULL, 1),
(966977, 113536, 24459, '<td valign="top">it''s nice and dreamy. well composed. the lines take the eyes to the tower in the background. It makes me want to look a bit longer.<br/>Nice job, man</td>', 'it''s nice and dreamy. well composed. the lines take the eyes to the tower in the background. It makes me want to look a bit longer.Nice job, man', '2004-10-20 14:51:11.000000', NULL, 1),
(966993, 113315, 20889, '<td valign="top">I do believe that this is my favorite of all so far...</td>', 'I do believe that this is my favorite of all so far...', '2004-10-20 15:03:13.000000', NULL, 1),
(967025, 113433, 11895, '<td valign="top">well executed shot but the composition is weak, you should have moved a few steps to get that street light out of the frame; the border is gimmicky</td>', 'well executed shot but the composition is weak, you should have moved a few steps to get that street light out of the frame; the border is gimmicky', '2004-10-20 15:22:00.000000', NULL, 1),
