(967401, 113127, 18219, '<td valign="top">great reflection of the lights.<br/>perfect exposure.<br/>very well done.</td>', 'great reflection of the lights.perfect exposure.very well done.', '2004-10-20 19:10:44.000000', NULL, 1),
