INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(967458, 113348, 17069, '<td valign="top">Very nice work! I''m impressed.<br/>Greets, Daniel</td>', 'Very nice work! I''m impressed.Greets, Daniel', '2004-10-20 19:48:27.000000', NULL, 1),
