(967464, 113429, 17069, '<td valign="top">toooooo bright. Next time DRI, maybe?<br/>Greets, Daniel</td>', 'toooooo bright. Next time DRI, maybe?Greets, Daniel', '2004-10-20 19:51:00.000000', NULL, 1),
(967466, 113563, 17069, '<td valign="top">hmmmm... looks like a snake on crack :o)<br/>Greets, Daniel</td>', 'hmmmm... looks like a snake on crack :o)Greets, Daniel', '2004-10-20 19:52:09.000000', NULL, 1),
