(970612, 113366, 10818, '<td valign="top">Beautiful colors, interesting and unique photo for this challenge.  Great title.</td>', 'Beautiful colors, interesting and unique photo for this challenge.  Great title.', '2004-10-23 08:45:07.000000', NULL, 1),
