(970916, 113495, 4517, '<td valign="top">Beautiful and perfect time of night with still some colour in the sky. 9</td>', 'Beautiful and perfect time of night with still some colour in the sky. 9', '2004-10-23 16:12:02.000000', NULL, 1),
(970927, 113171, 4517, '<td valign="top">Boats always look better from the front but not alot you could have done about it.  Seems to be running downhill right to left. 5</td>', 'Boats always look better from the front but not alot you could have done about it.  Seems to be running downhill right to left. 5', '2004-10-23 16:24:08.000000', NULL, 1),
