(970940, 113517, 4517, '<td valign="top">Amazing central 3rd of the photo. Needs a bit of the top and bottom or zooming in on a couple of the towers to fill the frame. 7</td>', 'Amazing central 3rd of the photo. Needs a bit of the top and bottom or zooming in on a couple of the towers to fill the frame. 7', '2004-10-23 16:34:23.000000', NULL, 1),
(970944, 113359, 4517, '<td valign="top">Oh no not already :)  Nice pic, maybe a slightly longer exposure would brighten it up a bit.</td>', 'Oh no not already :)  Nice pic, maybe a slightly longer exposure would brighten it up a bit.', '2004-10-23 16:37:59.000000', NULL, 1),
