(972375, 112924, 22734, '<td valign="top">This is a very good image and one to be proud of. A wonderful addition to any port.</td>', 'This is a very good image and one to be proud of. A wonderful addition to any port.', '2004-10-25 01:44:14.000000', NULL, 0),
(972387, 113117, 21245, '<td valign="top">I''ve been very suprised by the dramatic contrast in reactions to this shot.  These girls did a fantastic job of creating powerful and sensual imagery without being distasteful in the least.  The image was validated so I really don''t understand the continual accusations that it was a composite, especially considering the image placing 8th in the "Defining Feature" challenge being shot using the exact same technique.  <br/> <br/>A sincere thank you to everyone who took the time to vote, and especially comment.</td>', 'I''ve been very suprised by the dramatic contrast in reactions to this shot.  These girls did a fantastic job of creating powerful and sensual imagery without being distasteful in the least.  The image was validated so I really don''t understand the continual accusations that it was a composite, especially considering the image placing 8th in the "Defining Feature" challenge being shot using the exact same technique.   A sincere thank you to everyone who took the time to vote, and especially comment.', '2004-10-25 01:51:17.000000', NULL, 0),
(972412, 113517, 16301, '<td valign="top">I wonder why you had the refinery centered like that? Do you think the negative space in the bottom helps? Because the eye is lead up the frame following the steam. Just wondering :) The exposure is excellent though...<br/><br/><i>Message edited by author 2004-10-25 01:05:20.</i></td>', 'I wonder why you had the refinery centered like that? Do you think the negative space in the bottom helps? Because the eye is lead up the frame following the steam. Just wondering :) The exposure is excellent though...', '2004-10-25 02:04:54.000000', '2004-10-25 02:05:20.000000', 0),
(972443, 113504, 5728, '<td valign="top">Lucky you living in a place like that :) Congrats on your ribbon, I really like this image.</td>', 'Lucky you living in a place like that :) Congrats on your ribbon, I really like this image.', '2004-10-25 02:26:36.000000', NULL, 0),
(972444, 113024, 17103, '<td valign="top">I agree with graphicfunk, so surprised you didn''t ribbon!  Would love to know how you achieved the "painted" effect....</td>', 'I agree with graphicfunk, so surprised you didn''t ribbon!  Would love to know how you achieved the "painted" effect....', '2004-10-25 02:27:15.000000', NULL, 0),
(972448, 112717, 93, '<td valign="top">Still love this shot.. a 27th placing was far, far too low.<br/> <br/>Great shot, and keep up the good work!</td>', 'Still love this shot.. a 27th placing was far, far too low. Great shot, and keep up the good work!', '2004-10-25 02:29:45.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(972459, 113117, 27293, '<td valign="top">Don''t pay attention to all those that complain, they are just jealous, ''cause they have no idea that the coolest things can be done without photoshop.</td>', 'Don''t pay attention to all those that complain, they are just jealous, ''cause they have no idea that the coolest things can be done without photoshop.', '2004-10-25 02:38:11.000000', NULL, 0),
(972482, 113348, 19708, '<td valign="top">Well Nick, Congrats on your first ribbon.<br/>Anyone hanging their hardware outside their car deserves one IMO.<br/>Well Done!</td>', 'Well Nick, Congrats on your first ribbon.Anyone hanging their hardware outside their car deserves one IMO.Well Done!', '2004-10-25 02:58:05.000000', NULL, 0),
(972487, 113582, 19708, '<td valign="top">Try this with a cold hands and hand-held at 1/15 sec.<br/>Though many didn''t like the frame, I thought it needed definition.<br/> <br/>Considering the hardware I was up against in this one, I am jazzed at taking a 5 year-old technology camera and getting results like this.</td>', 'Try this with a cold hands and hand-held at 1/15 sec.Though many didn''t like the frame, I thought it needed definition. Considering the hardware I was up against in this one, I am jazzed at taking a 5 year-old technology camera and getting results like this.', '2004-10-25 03:02:20.000000', NULL, 0),
(972490, 113517, 11897, '<td valign="top">Gordon, I tend to agree with the comments on the foreground space and marked it down slightly for it.<br/>I bet the larger image is pin sharp, it looks that way.<br/>Overall quite an interesting, well taken shot and a very respectable place for yor first 20D nightshot.</td>', 'Gordon, I tend to agree with the comments on the foreground space and marked it down slightly for it.I bet the larger image is pin sharp, it looks that way.Overall quite an interesting, well taken shot and a very respectable place for yor first 20D nightshot.', '2004-10-25 03:04:56.000000', NULL, 0),
(972491, 113504, 19708, '<td valign="top">One a word - WOW!<br/>Congrats on the Blue here. The POV is great on this shot.<br/>(Hardware helped a bit too) LOL<br/> <br/>Well Done!</td>', 'One a word - WOW!Congrats on the Blue here. The POV is great on this shot.(Hardware helped a bit too) LOL Well Done!', '2004-10-25 03:06:01.000000', NULL, 0),
