(977322, 112544, 5112, '<td valign="top">Wow!  This almost looks like one of the old oil paintings, the tone is similar, and the feel/texture.  I like it very much.</td>', 'Wow!  This almost looks like one of the old oil paintings, the tone is similar, and the feel/texture.  I like it very much.', '2004-10-28 02:19:22.000000', NULL, 0),
(977406, 112773, 3087, '<td valign="top">This is a great shot strengthened by the lighting and colour cast. I''d personally crop out the entire left side to lose that row of bright white lights and maintain focus on your subject.</td>', 'This is a great shot strengthened by the lighting and colour cast. I''d personally crop out the entire left side to lose that row of bright white lights and maintain focus on your subject.', '2004-10-28 05:34:13.000000', NULL, 0),
