(1800234, 113504, 46142, '<td valign="top">Incredible image Amason.<br/>I wish I lived where I could see this.</td>', 'Incredible image Amason.I wish I lived where I could see this.', '2005-10-21 01:14:12.000000', NULL, 0),
(1866836, 113495, 15711, '<td valign="top">That''s one of the most well done color night images I''ve ever seen. The colors are so rich and vibrant. I love all of the illumination with the water in the foreground.  Spectacular reflections.</td>', 'That''s one of the most well done color night images I''ve ever seen. The colors are so rich and vibrant. I love all of the illumination with the water in the foreground.  Spectacular reflections.', '2005-11-14 22:18:00.000000', NULL, 0),
(1955966, 112717, 37961, '<td valign="top">Thisis a really powerful image. The colors/subject and mood are ever present. Excellent.</td>', 'Thisis a really powerful image. The colors/subject and mood are ever present. Excellent.', '2005-12-16 09:29:40.000000', NULL, 0),
(2104681, 113433, 12611, '<td valign="top">I think the composition here is lacking; You can''t just cut a building off a few feet from the ground and sow the sky above. Also the lampost is a bit too much; the light looks fake and digital.<br/> <br/>The borfer is a great Idead, but nothing can overcome the problems with angle and composition.</td>', 'I think the composition here is lacking; You can''t just cut a building off a few feet from the ground and sow the sky above. Also the lampost is a bit too much; the light looks fake and digital. The borfer is a great Idead, but nothing can overcome the problems with angle and composition.', '2006-01-31 08:36:11.000000', NULL, 0),
(2112337, 112717, 50466, '<td valign="top">i love this shot....the colors are great</td>', 'i love this shot....the colors are great', '2006-02-01 20:58:40.000000', NULL, 0),
(2127992, 113652, 12253, '<td valign="top">Missed this one before in your profile... Beautiful.  The colors and motion in this just make it sing!</td>', 'Missed this one before in your profile... Beautiful.  The colors and motion in this just make it sing!', '2006-02-06 21:43:39.000000', NULL, 0),
(2378438, 113167, 57166, '<td valign="top">This image would have been a 10 for me.  I love it.</td>', 'This image would have been a 10 for me.  I love it.', '2006-05-03 17:39:14.000000', NULL, 0),
(2390286, 113652, 57429, '<td valign="top">Beautiful lighting! Very nice</td>', 'Beautiful lighting! Very nice', '2006-05-07 17:09:11.000000', NULL, 0),
(2390339, 113652, 15711, '<td valign="top">WOW - looks like a poster.  IT is beautiful.  So smooth and the dim tones really work well.</td>', 'WOW - looks like a poster.  IT is beautiful.  So smooth and the dim tones really work well.', '2006-05-07 17:25:55.000000', NULL, 0),
(2390342, 112657, 15711, '<td valign="top">Just ran across this. Excellent shot.  Love the single focused subject, with the movement of the others walking past.  Well done.</td>', 'Just ran across this. Excellent shot.  Love the single focused subject, with the movement of the others walking past.  Well done.', '2006-05-07 17:26:55.000000', NULL, 0),
(2390346, 112717, 15711, '<td valign="top">I really like the bright colors. Makes the guy with the hood really pop. The diagonal line of the staircase makes your eye look at the entire image, then come back to the subject.</td>', 'I really like the bright colors. Makes the guy with the hood really pop. The diagonal line of the staircase makes your eye look at the entire image, then come back to the subject.', '2006-05-07 17:28:08.000000', NULL, 0),
(2440971, 112648, 48717, '<td valign="top">Wow, this is very nice.  The colors are wonderful, and the exposure is just right.</td>', 'Wow, this is very nice.  The colors are wonderful, and the exposure is just right.', '2006-05-20 18:16:59.000000', NULL, 0),
(2608765, 112717, 60799, '<td valign="top">This is a brilliant shot.  The colors are soooo wonderfull.  How did the model stand that still for 30 seconds though... I''ve tried similar shots and never gotten them that sharp.</td>', 'This is a brilliant shot.  The colors are soooo wonderfull.  How did the model stand that still for 30 seconds though... I''ve tried similar shots and never gotten them that sharp.', '2006-07-10 21:55:39.000000', NULL, 0),
(2649489, 112357, 46294, '<td valign="top">This is soooo lovely! Could have been the factory in Charlie and the chocolate factory!!!</td>', 'This is soooo lovely! Could have been the factory in Charlie and the chocolate factory!!!', '2006-07-22 18:28:39.000000', NULL, 0),
(2697587, 113652, 42013, '<td valign="top">Great job on this pic.  love the softenss of the clouds and your center positioning of the lighthouse was a perfect compositional choice.</td>', 'Great job on this pic.  love the softenss of the clouds and your center positioning of the lighthouse was a perfect compositional choice.', '2006-08-05 17:15:30.000000', NULL, 0),
(2722349, 113652, 39181, '<td valign="top">Excellent shot.  I love these photos and you have a great PF!!</td>', 'Excellent shot.  I love these photos and you have a great PF!!', '2006-08-13 11:48:04.000000', NULL, 0),
(3193041, 113579, 65025, '<td valign="top">Hey, I live by this building too!  I''m from Butte.  I go to school in Idaho, and come back during Christmas/spring break and some times in the summers.</td>', 'Hey, I live by this building too!  I''m from Butte.  I go to school in Idaho, and come back during Christmas/spring break and some times in the summers.', '2007-01-07 21:28:37.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3289555, 113259, 46177, '<td valign="top">Hadn''t seen this before but it really is a beautiful image, love the colours and reflections! The water looks like glass.</td>', 'Hadn''t seen this before but it really is a beautiful image, love the colours and reflections! The water looks like glass.', '2007-01-27 00:34:00.000000', NULL, 0),
(3460668, 112544, 63269, '<td valign="top">I cannot believe this got such a low score! Well, okay, I guess it''s not THAT low, but surely this deserved at least a 6 something, possibly a 7! The voters just don''t like dark photos, I guess. :( <br/> <br/>Anyways, the atmosphere this evokes... is stunning. It''s so subtle - you''ve got to look at the picture for a second to see it, but it''s there. Everything about this is just awesome!</td>', 'I cannot believe this got such a low score! Well, okay, I guess it''s not THAT low, but surely this deserved at least a 6 something, possibly a 7! The voters just don''t like dark photos, I guess. :(  Anyways, the atmosphere this evokes... is stunning. It''s so subtle - you''ve got to look at the picture for a second to see it, but it''s there. Everything about this is just awesome!', '2007-03-14 12:48:50.000000', NULL, 0),
(4018530, 113504, 59267, '<td valign="top">Beautiful aurora shot! Excellent and well deserved the blue ribbon. I wish I can have at least one chance to see aurora.</td>', 'Beautiful aurora shot! Excellent and well deserved the blue ribbon. I wish I can have at least one chance to see aurora.', '2007-08-21 21:11:24.000000', NULL, 0),
(4119967, 112718, 34659, '<td valign="top">Great shot!  Love the HDR feel.</td>', 'Great shot!  Love the HDR feel.', '2007-09-27 12:00:27.000000', NULL, 0),
(4641628, 112657, 37719, '<td valign="top">Very nice photo.  I like the composition and the balance of placement within the frame.  The selective movement adds a dramatic flare I can appreciate.  Well done, nice shot.</td>', 'Very nice photo.  I like the composition and the balance of placement within the frame.  The selective movement adds a dramatic flare I can appreciate.  Well done, nice shot.', '2008-04-15 21:30:48.000000', NULL, 0),
(5497041, 113652, 106576, '<td valign="top">Wow,<br/>The sky really makes this shot to me!!<br/>Beautiful!!</td>', 'Wow,The sky really makes this shot to me!!Beautiful!!', '2009-05-23 02:46:01.000000', NULL, 0);
